/*com.moyeo.mapper.UserMapper.updateUserProfile*/
UPDATE USER_MAST A
  JOIN ROOM_USER_MAP B
    ON B.USER_ID = A.USER_ID
   SET A.USER_NM = #{userName, jdbcType=VARCHAR}
     , A.USER_IMG = #{userImg, jdbcType=INTEGER}
 WHERE B.ROOM_ID = #{roomId}
   AND A.USER_ID = #{userId}

